LINES = {"R14. ": R14, "3.2 Environment. ": ENV, "Step 1. ": STEP1, "Step 2. ": STEP2, "Step 3. ": STEP3,
         "Step 4. ": STEP4, "Step 6. ": STEP6}
LINES.update(BULLETS)

CORE_BULLET = """- Start from the core properties in the file STIR-L4_core_properties_v1.0.csv, which the team gives you with this prompt: properties that apply to any review of health research, each with its type, grain and levels. Add review-specific ones. The file also lists one derived field (validation-to-development relatedness), which is computed by a declared rule and is not a property. If the team has not provided it, ask for it, or draft levels as a DRAFT for a reviewer to certify; never reproduce the file from memory."""


def build():
    text = open(SRC, encoding="utf-8").read()
    for old, new in EDITS:
        n = text.count(old)
        assert n == 1, (n, old[:80])
        text = text.replace(old, new)
    out = []
    used = set()
    for line in text.split("\n"):
        key = next((k for k in LINES if line.startswith(k)), None)
        if key:
            assert key not in used, key
            used.add(key)
            out.append(LINES[key])
        elif line.startswith("- Start from these core properties"):
            used.add("core")
            out.append(CORE_BULLET)
        else:
            out.append(line)
    missing = (set(LINES) | {"core"}) - used
    assert not missing, missing
    text = "\n".join(out)
    text = text.replace("e-mail", "email")
    assert "version 1.0" not in text and "prompt_v1.0" not in text
    assert not re.search(r"\bR15\b", text)
    return text


if __name__ == "__main__":
    t = build()
    open(OUT, "w", encoding="utf-8").write(t)
    print(f"wrote {OUT}: {len(t.split())} words")
